css:
.bestself-sim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #243043;
    background: linear-gradient(160deg, #f5f7fa 0%, #eef2f6 100%);
    border-radius: 16px;
    line-height: 1.55;
}

.bestself-sim-header {
    text-align: center;
    padding: 28px 20px;
    background: linear-gradient(135deg, #0f766e 0%, #115e59 60%, #134e4a 100%);
    border-radius: 14px;
    color: #f0fdfa;
    box-shadow: 0 10px 30px rgba(15, 118, 110, 0.25);
}

.bestself-sim-header h1 {
    margin: 0 0 6px;
    font-size: 2rem;
    font-weight: 700;
    letter-spacing: -0.5px;
}

.bestself-sim-header p {
    margin: 0;
    font-size: 1rem;
    color: #99f6e4;
}

.bestself-sim-context-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    margin: 20px 0;
}

.bestself-sim-context-item {
    flex: 1 1 180px;
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
    box-shadow: 0 2px 6px rgba(36, 48, 67, 0.05);
}

.bestself-sim-context-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: #64748b;
    font-weight: 600;
}

.bestself-sim-context-value {
    font-size: 1.05rem;
    font-weight: 700;
    color: #1e293b;
}

.bestself-sim-context-value.bestself-sim-constraint {
    color: #b91c1c;
}

.bestself-sim-period-counter {
    text-align: center;
    font-size: 0.95rem;
    font-weight: 600;
    color: #0f766e;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin: 14px 0 22px;
}

.bestself-sim-period-counter #currentDay,
.bestself-sim-period-counter #maxPeriods {
    font-size: 1.2rem;
    color: #134e4a;
}

.bestself-sim-dashboard {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 22px;
}

.bestself-sim-kpi-card {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 16px;
    border: 1px solid #e2e8f0;
    box-shadow: 0 4px 12px rgba(36, 48, 67, 0.06);
    transition: transform 0.2s ease;
}

.bestself-sim-kpi-card:hover {
    transform: translateY(-2px);
}

.bestself-sim-kpi-primary {
    border-top: 4px solid #0f766e;
}

.bestself-sim-kpi-label {
    font-size: 0.78rem;
    font-weight: 600;
    color: #475569;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    margin-bottom: 8px;
    min-height: 2.1em;
}

.bestself-sim-kpi-value {
    font-size: 2.5rem;
    font-weight: 800;
    color: #0f766e;
    line-height: 1;
    letter-spacing: -1px;
}

.bestself-sim-value-danger {
    color: #dc2626;
}

.bestself-sim-kpi-bar {
    height: 8px;
    background: #e2e8f0;
    border-radius: 6px;
    overflow: hidden;
    margin: 10px 0 6px;
}

.bestself-sim-kpi-fill {
    height: 100%;
    background: linear-gradient(90deg, #14b8a6, #0f766e);
    border-radius: 6px;
    transition: width 0.6s ease;
}

.bestself-sim-fill-intrinsic {
    background: linear-gradient(90deg, #38bdf8, #0284c7);
}

.bestself-sim-fill-perf {
    background: linear-gradient(90deg, #a3e635, #65a30d);
}

.bestself-sim-fill-danger {
    background: linear-gradient(90deg, #f87171, #dc2626);
}

.bestself-sim-kpi-sublabel {
    font-size: 0.7rem;
    color: #94a3b8;
    font-weight: 500;
}

.bestself-sim-scenario-panel {
    background: #ffffff;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 18px;
    border-left: 5px solid #f59e0b;
    box-shadow: 0 4px 14px rgba(36, 48, 67, 0.06);
}

.bestself-sim-scenario-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
    flex-wrap: wrap;
}

.bestself-sim-round-badge {
    background: #f59e0b;
    color: #ffffff;
    font-size: 0.75rem;
    font-weight: 700;
    padding: 4px 12px;
    border-radius: 20px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.bestself-sim-scenario-header h3 {
    margin: 0;
    font-size: 1.3rem;
    color: #1e293b;
    font-weight: 700;
}

.bestself-sim-scenario-text {
    font-size: 0.98rem;
    color: #334155;
    margin-bottom: 14px;
}

.bestself-sim-briefing {
    background: #fffbeb;
    border: 1px dashed #fbbf24;
    border-radius: 10px;
    padding: 12px 16px;
    font-size: 0.92rem;
    color: #92400e;
}

.bestself-sim-briefing-tag {
    display: inline-block;
    background: #f59e0b;
    color: #fff;
    font-size: 0.65rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 2px 8px;
    border-radius: 5px;
    margin-right: 8px;
    vertical-align: middle;
}

.bestself-sim-decision-panel {
    background: #ffffff;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(36, 48, 67, 0.06);
}

.bestself-sim-decision-panel h3 {
    margin: 0 0 8px;
    font-size: 1.2rem;
    color: #0f766e;
    font-weight: 700;
}

.bestself-sim-decision-context {
    font-size: 0.95rem;
    color: #475569;
    margin-bottom: 18px;
    font-style: italic;
}

.bestself-sim-options {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-bottom: 20px;
}

.bestself-sim-option-btn {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    text-align: left;
    gap: 6px;
    background: #f8fafc;
    border: 2px solid #e2e8f0;
    border-radius: 10px;
    padding: 14px 18px;
    cursor: pointer;
    transition: all 0.18s ease;
    width: 100%;
}

.bestself-sim-option-btn:hover {
    border-color: #14b8a6;
    background: #f0fdfa;
}

.bestself-sim-option-btn.selected {
    border-color: #0f766e;
    background: #ccfbf1;
    box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.15);
}

.bestself-sim-option-label {
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: #0f766e;
}

.bestself-sim-option-text {
    font-size: 0.95rem;
    color: #1e293b;
    font-weight: 500;
}

.bestself-sim-submit-btn {
    width: 100%;
    background: linear-gradient(135deg, #0f766e, #115e59);
    color: #ffffff;
    border: none;
    border-radius: 10px;
    padding: 14px;
    font-size: 1.05rem;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s ease;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.bestself-sim-submit-btn:hover:not(:disabled) {
    background: linear-gradient(135deg, #115e59, #134e4a);
    transform: translateY(-1px);
}

.bestself-sim-submit-btn:disabled {
    background: #cbd5e1;
    color: #94a3b8;
    cursor: not-allowed;
}

.bestself-sim-feedback-panel {
    background: #ecfeff;
    border: 1px solid #67e8f9;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 18px;
}

.bestself-sim-feedback-header {
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: #0e7490;
    margin-bottom: 10px;
}

.bestself-sim-feedback-text {
    font-size: 1rem;
    color: #164e63;
    margin-bottom: 14px;
}

.bestself-sim-impact-summary {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}

.bestself-sim-impact-item {
    font-size: 0.82rem;
    font-weight: 700;
    padding: 6px 12px;
    border-radius: 8px;
    background: #ffffff;
    border: 1px solid #cbd5e1;
}

.bestself-sim-impact-item.positive {
    color: #15803d;
    border-color: #86efac;
    background: #f0fdf4;
}

.bestself-sim-impact-item.negative {
    color: #b91c1c;
    border-color: #fca5a5;
    background: #fef2f2;
}

.bestself-sim-impact-item.neutral {
    color: #475569;
}

.bestself-sim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px;
    margin-bottom: 18px;
    height: 340px;
    box-shadow: 0 4px 14px rgba(36, 48, 67, 0.06);
}

.bestself-sim-history {
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    margin-bottom: 18px;
    overflow-x: auto;
    box-shadow: 0 4px 14px rgba(36, 48, 67, 0.06);
}

.bestself-sim-history table {
    width: 100%;
    font-size: 0.88rem;
    color: #334155;
}

.bestself-sim-history table th {
    color: #0f766e;
    font-weight: 700;
    border-bottom: 2px solid #e2e8f0;
}

.bestself-sim-final-panel {
    background: linear-gradient(135deg, #134e4a 0%, #0f766e 100%);
    border-radius: 16px;
    padding: 32px;
    color: #f0fdfa;
    text-align: center;
    box-shadow: 0 12px 36px rgba(15, 118, 110, 0.3);
}

.bestself-sim-final-panel h2 {
    margin: 0 0 16px;
    font-size: 1.7rem;
    font-weight: 800;
}

.bestself-sim-verdict {
    font-size: 1.5rem;
    font-weight: 800;
    margin-bottom: 20px;
    letter-spacing: -0.5px;
}

.bestself-sim-final-metrics {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 22px;
}

.bestself-sim-final-metric {
    background: rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    padding: 16px 12px;
    border: 1px solid rgba(255, 255, 255, 0.15);
}

.bestself-sim-final-metric-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #99f6e4;
    margin-bottom: 6px;
}

.bestself-sim-final-metric-value {
    font-size: 1.8rem;
    font-weight: 800;
    color: #ffffff;
}

.bestself-sim-final-narrative {
    font-size: 1rem;
    color: #ccfbf1;
    text-align: left;
    background: rgba(0, 0, 0, 0.15);
    border-radius: 10px;
    padding: 18px 22px;
    line-height: 1.6;
}

select,
input[type="number"],
input[type="text"] {
    background-color: #ffffff;
    color: #1e293b;
    border: 1px solid #cbd5e1;
    border-radius: 8px;
    padding: 8px 10px;
    font-size: 0.95rem;
}

select option {
    background-color: #ffffff;
    color: #1e293b;
}

@media (max-width: 768px) {
    .bestself-sim-container {
        padding: 14px;
    }
    .bestself-sim-dashboard,
    .bestself-sim-final-metrics {
        grid-template-columns: repeat(2, 1fr);
    }
    .bestself-sim-header h1 {
        font-size: 1.5rem;
    }
    .bestself-sim-kpi-value {
        font-size: 2rem;
    }
    .bestself-sim-chart {
        height: 280px;
    }
}


/* FIX v1.1.0 — completion / client-debrief screen */
.abs-completion { padding: 10px 6px; text-align: center; }
.abs-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.abs-completion-verdict { font-size: 20px; font-weight: 700; color: #0f172a; margin-bottom: 8px; }
.abs-completion-score { font-size: 16px; color: #0f172a; margin-bottom: 14px; }
.abs-completion-score strong { color: #0369a1; }
.abs-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.abs-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 104px; }
.abs-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.abs-completion-metric strong { font-size: 16px; color: #0f172a; }
.abs-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 680px; text-align: left; }
.abs-completion-insights li { padding: 10px 14px; margin-bottom: 8px; background: #f0f9ff; border-left: 3px solid #0369a1; border-radius: 4px; color: #1e293b; font-size: 14px; }

