        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    engagement: 48,
                    intrinsic: 42,
                    performance: 61,
                    turnover: 52,
                    slaBreached: false,
                    trapsHit: [],
                    engagementHistory: [48],
                    intrinsicHistory: [42],
                    performanceHistory: [61],
                    turnoverHistory: [52]
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { selectedOption: null };
            }
            this._renderRound(state);
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            if (this.selectedOption === null || !Number.isFinite(this.selectedOption)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_option_warning'), 'warning'
                );
                return false;
            }
            decisions.selectedOption = this.selectedOption;
            return true;
        }

        calculateResults(state) {
            const round = this.ROUNDS[state.currentPeriod - 1];
            const opt = round.options[state.decisions.selectedOption];
            const ds = state.domainState;

            // SLA breach: an unbounded-freedom move can shatter the client's service levels.
            let slaBreachedThisRound = false;
            if (typeof opt.slaRisk === 'number' && opt.slaRisk > 0.5) {
                slaBreachedThisRound = true;
                ds.slaBreached = true;
            }

            let engDelta = opt.engDelta;
            let intDelta = opt.intDelta;
            let perfDelta = opt.perfDelta;
            let turnDelta = opt.turnDelta;

            // A breached SLA caps the performance damage at a hard floor — the contract is on fire.
            if (slaBreachedThisRound) {
                perfDelta = Math.min(perfDelta, -10);
            }

            if (opt.trap) {
                if (!ds.trapsHit.includes(opt.trap)) ds.trapsHit.push(opt.trap);
            }

            ds.engagement = Math.max(0, Math.min(100, ds.engagement + engDelta));
            ds.intrinsic = Math.max(0, Math.min(100, ds.intrinsic + intDelta));
            ds.performance = Math.max(0, Math.min(100, ds.performance + perfDelta));
            ds.turnover = Math.max(0, Math.min(100, ds.turnover + turnDelta));

            ds.engagementHistory.push(ds.engagement);
            ds.intrinsicHistory.push(ds.intrinsic);
            ds.performanceHistory.push(ds.performance);
            ds.turnoverHistory.push(ds.turnover);

            const lang = window.mySimulation.language || 'en';
            const feedbackText = lang === 'es' ? opt.feedback_es : opt.feedback;
            this._showFeedback(feedbackText, { engDelta, intDelta, perfDelta, turnDelta });

            this.selectedOption = null;

            if (state.currentPeriod >= this.ROUNDS.length) {
                setTimeout(() => this._showFinalResults(state), 1100);
            } else {
                setTimeout(() => {
                    this._renderRound(window.mySimulation.state);
                    this._updateBriefing(window.mySimulation.state);
                }, 500);
            }

            // v1.1.0 FIX A — surface the composite recovery score on the reporting-layer
            // paths (express_resolveDomainScore reads top-level domainState.score; the
            // trend reads results.score/overallScore). domainState.performance is a DOMAIN
            // metric (CSAT) and is deliberately NOT reused. Scoring math unchanged.
            ds.score = Math.round(this._compositeScore(ds));
            return {
                period: state.currentPeriod,
                score: ds.score,
                overallScore: ds.score,
                round: round.id,
                engagement: ds.engagement,
                intrinsic: ds.intrinsic,
                performance: ds.performance,
                turnover: ds.turnover,
                slaBreached: ds.slaBreached,
                engDelta: engDelta,
                intDelta: intDelta
            };
        }

        _replacementCost(state) {
            // 60-advisor team; replacement cost £4,200 each. Annualised leavers ~ turnover% of 60.
            const ds = state.domainState;
            const leavers = Math.round((ds.turnover / 100) * 60);
            return leavers * 4200;
        }

        _compositeScore(ds) {
            // Weighted recovery score. Turnover inverted (lower is better).
            const turnoverScore = 100 - ds.turnover;
            let score = ds.engagement * 0.35 + ds.intrinsic * 0.3 + ds.performance * 0.2 + turnoverScore * 0.15;
            if (ds.slaBreached) score -= 20; // a breached SLA puts the whole contract at risk
            return Math.max(0, Math.min(100, score));
        }

        _showFeedback(text, deltas) {
            const panel = document.getElementById('feedbackPanel');
            const feedbackText = document.getElementById('feedbackText');
            const impactSummary = document.getElementById('impactSummary');
            if (!panel || !feedbackText || !impactSummary) return;

            const t = (k) => window.mySimulation.t(k);
            feedbackText.textContent = text;

            const item = (labelKey, val, invert) => {
                const good = invert ? val < 0 : val > 0;
                const bad = invert ? val > 0 : val < 0;
                const cls = good ? 'positive' : bad ? 'negative' : 'neutral';
                const sign = val > 0 ? '+' : '';
                return `<span class="bestself-sim-impact-item ${cls}">${t(labelKey)}: ${sign}${val}</span>`;
            };

            impactSummary.innerHTML =
                item('engagement_label', deltas.engDelta, false) +
                item('intrinsic_label', deltas.intDelta, false) +
                item('performance_label', deltas.perfDelta, false) +
                item('turnover_label', deltas.turnDelta, true);

            panel.style.display = 'block';
            panel.scrollIntoView({ behavior: 'smooth' });
        }

        _updateBriefing(state) {
            const round = this.ROUNDS[(state.currentPeriod || 1) - 1];
            if (!round) return;
            const lang = window.mySimulation ? window.mySimulation.language : 'en';
            const box = document.getElementById('briefingText');
            if (!box) return;
            const key = 'briefing_round' + round.id;
            box.textContent = window.mySimulation ? window.mySimulation.t(key) : '';
            void lang;
        }

        _renderRound(state) {
            const period = state.currentPeriod || 1;
            const round = this.ROUNDS[period - 1];
            const lang = window.mySimulation ? window.mySimulation.language : 'en';
            if (!round) return;

            const badge = document.getElementById('roundBadge');
            const title = document.getElementById('scenarioTitle');
            const text = document.getElementById('scenarioText');
            const context = document.getElementById('decisionContext');

            if (badge) badge.textContent = (window.mySimulation ? window.mySimulation.t('round_label') : 'Round') + ' ' + round.id;
            if (title) title.textContent = lang === 'es' ? round.title_es : round.title;
            if (text) text.textContent = lang === 'es' ? round.description_es : round.description;
            if (context) context.textContent = lang === 'es' ? round.context_es : round.context;

            const optionsContainer = document.getElementById('decisionOptions');
            if (optionsContainer) {
                optionsContainer.innerHTML = round.options.map((opt, idx) => {
                    const label = String.fromCharCode(65 + idx);
                    const optText = lang === 'es' ? opt.text_es : opt.text;
                    const div = document.createElement('div');
                    div.textContent = optText;
                    return `<button class="bestself-sim-option-btn" data-option="${idx}" id="opt${idx}">`
                        + `<span class="bestself-sim-option-label">${(window.mySimulation ? window.mySimulation.t('option_word') : 'Option')} ${label}</span>`
                        + `<span class="bestself-sim-option-text">${div.innerHTML}</span>`
                        + `</button>`;
                }).join('');
            }

            setTimeout(() => this._attachOptionListeners(), 80);

            const submitBtn = document.getElementById('nextPeriodBtn');
            if (submitBtn) submitBtn.disabled = true;
            this.selectedOption = null;

            const feedbackPanel = document.getElementById('feedbackPanel');
            if (feedbackPanel) feedbackPanel.style.display = 'none';
        }

        _attachOptionListeners() {
            const options = document.querySelectorAll('.bestself-sim-option-btn');
            options.forEach((btn) => {
                btn.addEventListener('click', () => {
                    options.forEach((b) => b.classList.remove('selected'));
                    btn.classList.add('selected');
                    this.selectedOption = parseInt(btn.dataset.option, 10);
                    const submitBtn = document.getElementById('nextPeriodBtn');
                    if (submitBtn) submitBtn.disabled = false;
                });
            });
        }

        _showFinalResults(state) {
            const panel = document.getElementById('finalPanel');
            if (!panel) return;
            const ds = state.domainState;
            const lang = window.mySimulation.language || 'en';
            const t = (k) => window.mySimulation.t(k);

            const score = this._compositeScore(ds);
            const verdict = this.VERDICTS.find((v) => score >= v.min);
            const verdictName = lang === 'es' ? verdict.name_es : verdict.name;

            const verdictEl = document.getElementById('verdictDisplay');
            if (verdictEl) {
                verdictEl.textContent = verdictName;
                verdictEl.style.color = score >= 78 ? '#a7f3d0' : score >= 66 ? '#bbf7d0' : score >= 55 ? '#fde68a' : '#fca5a5';
            }

            const cost = this._replacementCost(state);
            const metricsEl = document.getElementById('finalMetrics');
            if (metricsEl) {
                metricsEl.innerHTML =
                    this._metricCard(t('engagement_label'), Math.round(ds.engagement) + '/100') +
                    this._metricCard(t('intrinsic_label'), Math.round(ds.intrinsic) + '/100') +
                    this._metricCard(t('performance_label'), Math.round(ds.performance) + '/100') +
                    this._metricCard(t('turnover_label'), Math.round(ds.turnover) + '%');
            }

            const narrativeEl = document.getElementById('finalNarrative');
            if (narrativeEl) {
                let lines = [];
                if (ds.slaBreached) {
                    lines.push(t('narr_sla'));
                }
                if (ds.trapsHit.includes('money')) lines.push(t('narr_money'));
                if (ds.trapsHit.includes('control')) lines.push(t('narr_control'));
                if (ds.trapsHit.includes('generic')) lines.push(t('narr_generic'));
                if (ds.trapsHit.includes('freedom')) lines.push(t('narr_freedom'));
                if (ds.trapsHit.includes('deficit')) lines.push(t('narr_deficit'));
                if (ds.trapsHit.length === 0 && !ds.slaBreached) lines.push(t('narr_clean'));

                const costLine = t('narr_cost').replace('{cost}', '£' + cost.toLocaleString('en-GB'));
                lines.push(costLine);
                lines.push(score >= 66 ? t('narr_win') : t('narr_lose'));

                narrativeEl.innerHTML = lines.map((l) => '<div>• ' + l + '</div>').join('');
            }

            panel.style.display = 'block';
            panel.scrollIntoView({ behavior: 'smooth' });
        }

